        }

        /* Responsive */
        @media (max-width: 768px) {
            .hero-title { font-size: 48px; }
            .section-title { font-size: 32px; }
            .parallax-text { font-size: 36px; }
            nav { padding: 15px 20px; }
            .nav-links { gap: 15px; }
