            background: rgba(5, 5, 5, 0.95);
            border-bottom: 1px solid rgba(212, 175, 55, 0.3);
        }

        .logo {
            font-family: 'Playfair Display', serif;
            font-size: 28px;
            font-weight: 700;
            letter-spacing: 4px;
            color: var(--white-pure);
            position: relative;
        }

        .logo span {
            color: var(--gold-primary);
        }

        .logo::after {
            content: '';
            position: absolute;
            bottom: -8px;
            left: 0;
            width: 30px;
            height: 1px;
            background: var(--gold-primary);
            transition: width 0.5s ease;
        }

        .logo:hover::after {
            width: 100%;
        }

        .nav-links {
            display: flex;
            gap: 50px;
            list-style: none;
        }

        .nav-links a {
            color: var(--white-muted);
            text-decoration: none;
            font-size: 12px;
            font-weight: 500;
            letter-spacing: 3px;
            text-transform: uppercase;
            position: relative;
            transition: color 0.4s;
            padding: 5px 0;
        }

        .nav-links a::before {
            content: '';
            position: absolute;
            bottom: -5px;
            left: 50%;
            width: 0;
            height: 1px;
            background: var(--gold-primary);
            transition: all 0.4s ease;
            transform: translateX(-50%);
        }

        .nav-links a:hover {
            color: var(--gold-primary);
        }

        .nav-links a:hover::before {
            width: 100%;
        }

        /* Hero Section */
        .hero {
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            overflow: hidden;
        }

        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: 
                radial-gradient(ellipse at 20% 50%, rgba(212, 175, 55, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 50%, rgba(212, 175, 55, 0.05) 0%, transparent 50%),
                linear-gradient(180deg, var(--black-deep) 0%, var(--black-soft) 100%);
        }

        .hero-content {
            text-align: center;
            z-index: 10;
            padding: 0 20px;
        }

        .hero-eyebrow {
            font-size: 12px;
            letter-spacing: 8px;
            text-transform: uppercase;
            color: var(--gold-primary);
            margin-bottom: 30px;
            opacity: 0;
            animation: fadeInUp 1s 0.5s forwards;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 20px;
        }

        .hero-eyebrow::before,
        .hero-eyebrow::after {
            content: '';
            width: 40px;
            height: 1px;
            background: var(--gold-primary);
        }

        .hero-title {
            font-family: 'Playfair Display', serif;
            font-size: clamp(48px, 10vw, 140px);
            font-weight: 700;
            letter-spacing: 8px;
            line-height: 1;
            margin-bottom: 30px;
            background: linear-gradient(135deg, var(--white-pure) 0%, var(--gold-light) 50%, var(--white-pure) 100%);
            background-size: 200% auto;
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            animation: titleShimmer 5s linear infinite;
            opacity: 0;
            animation: fadeInUp 1.2s 0.8s forwards, titleShimmer 5s linear infinite;
        }

        @keyframes titleShimmer {
            to { background-position: 200% center; }
        }

        .hero-subtitle {
            font-family: 'Cormorant Garamond', serif;
            font-size: clamp(18px, 2.5vw, 28px);
            font-weight: 300;
            font-style: italic;
            color: var(--white-muted);
            margin-bottom: 50px;
            letter-spacing: 2px;
            opacity: 0;
            animation: fadeInUp 1s 1.2s forwards;
        }

        .hero-divider {
            width: 1px;
            height: 80px;
            background: linear-gradient(180deg, transparent, var(--gold-primary), transparent);
            margin: 0 auto 50px;
            opacity: 0;
            animation: fadeInUp 1s 1.5s forwards;
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(40px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .cta-button {
            padding: 22px 60px;
            font-family: 'Montserrat', sans-serif;
            font-size: 12px;
            font-weight: 600;
            letter-spacing: 4px;
            text-transform: uppercase;
            border: 1px solid var(--gold-primary);
            background: transparent;
            color: var(--gold-primary);
            cursor: pointer;
            position: relative;
            overflow: hidden;
            transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
            opacity: 0;
            animation: fadeInUp 1s 1.8s forwards;
        }

        .cta-button::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(212, 175, 55, 0.2), transparent);
            transition: left 0.6s;
        }

        .cta-button:hover {
            background: var(--gold-primary);
            color: var(--black-deep);
            letter-spacing: 6px;
            box-shadow: 0 0 40px rgba(212, 175, 55, 0.4);
        }

        .cta-button:hover::before {
            left: 100%;
        }

        /* Scroll Indicator */
        .scroll-indicator {
            position: absolute;
            bottom: 40px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 15px;
            opacity: 0;
            animation: fadeInUp 1s 2.2s forwards;
        }

        .scroll-text {
            font-size: 10px;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--gold-primary);
        }

        .scroll-line {
            width: 1px;
            height: 40px;
            background: rgba(212, 175, 55, 0.3);
            position: relative;
            overflow: hidden;
        }

        .scroll-line::after {
            content: '';
            position: absolute;
            top: -100%;
            left: 0;
            width: 100%;
            height: 100%;
            background: var(--gold-primary);
            animation: scrollDown 2s ease-in-out infinite;
        }

        @keyframes scrollDown {
            0% { top: -100%; }
            100% { top: 100%; }
        }

        /* Sections */
        section {
            padding: 150px 60px;
            position: relative;
            z-index: 1;
        }

        .section-header {
            text-align: center;
            margin-bottom: 100px;
        }

        .section-eyebrow {
            font-size: 11px;
            letter-spacing: 6px;
            text-transform: uppercase;
            color: var(--gold-primary);
            margin-bottom: 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 20px;
        }

        .section-eyebrow::before,
        .section-eyebrow::after {
            content: '';
            width: 30px;
            height: 1px;
            background: var(--gold-primary);
        }

        .section-title {
            font-family: 'Playfair Display', serif;
            font-size: clamp(36px, 5vw, 64px);
            font-weight: 700;
            letter-spacing: 4px;
            color: var(--white-pure);
            margin-bottom: 20px;
        }

        .section-title span {
            font-style: italic;
            color: var(--gold-primary);
            font-weight: 400;
        }

        .section-subtitle {
            font-family: 'Cormorant Garamond', serif;
            font-size: 20px;
            font-style: italic;
            color: var(--white-muted);
            letter-spacing: 1px;
        }

        /* Cards Grid */
        .cards-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
            gap: 30px;
            max-width: 1400px;
            margin: 0 auto;
        }

        .card {
            background: linear-gradient(135deg, var(--black-card) 0%, rgba(20, 20, 20, 0.8) 100%);
            border: 1px solid rgba(212, 175, 55, 0.15);
            padding: 50px 40px;
            position: relative;
            overflow: hidden;
            transition: all 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
            cursor: pointer;
        }

        .card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 2px;
            background: linear-gradient(90deg, transparent, var(--gold-primary), transparent);
            transform: translateX(-100%);
            transition: transform 0.8s ease;
        }

        .card::after {
            content: '';
            position: absolute;
            bottom: 0;
            right: 0;
            width: 100px;
            height: 100px;
            background: radial-gradient(circle, rgba(212, 175, 55, 0.1), transparent);
            opacity: 0;
            transition: opacity 0.6s;
        }

        .card:hover {
            border-color: rgba(212, 175, 55, 0.5);
            transform: translateY(-10px);
            box-shadow: 0 30px 60px rgba(0, 0, 0, 0.5), 0 0 40px rgba(212, 175, 55, 0.1);
        }

        .card:hover::before {
            transform: translateX(100%);
        }

        .card:hover::after {
            opacity: 1;
        }

        .card-number {
            font-family: 'Playfair Display', serif;
            font-size: 48px;
            color: var(--gold-primary);
            opacity: 0.3;
            margin-bottom: 20px;
            font-weight: 700;
        }

        .card-icon {
            font-size: 36px;
            margin-bottom: 25px;
            display: inline-block;
            filter: grayscale(100%) brightness(2);
            transition: filter 0.5s;
        }

        .card:hover .card-icon {
            filter: grayscale(0%) brightness(1);
        }

        .card h3 {
            font-family: 'Playfair Display', serif;
            font-size: 24px;
            margin-bottom: 15px;
            color: var(--white-pure);
            letter-spacing: 2px;
            font-weight: 600;
        }

        .card p {
            font-size: 14px;
            line-height: 1.8;
            color: var(--white-muted);
            letter-spacing: 0.5px;
        }

        .card-link {
            display: inline-block;
            margin-top: 25px;
            font-size: 11px;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--gold-primary);
            text-decoration: none;
            position: relative;
            padding-bottom: 5px;
            transition: letter-spacing 0.4s;
        }

        .card-link::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            height: 1px;
            background: var(--gold-primary);
            transform: scaleX(0);
            transform-origin: right;
            transition: transform 0.4s ease;
        }

        .card:hover .card-link {
            letter-spacing: 5px;
        }

        .card:hover .card-link::after {
            transform: scaleX(1);
            transform-origin: left;
        }

        /* Luxury Divider */
        .luxury-divider {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 30px;
            padding: 80px 0;
        }

        .luxury-divider .line {
            width: 100px;
            height: 1px;
            background: linear-gradient(90deg, transparent, var(--gold-primary), transparent);
        }

        .luxury-divider .diamond {
            width: 12px;
            height: 12px;
            border: 1px solid var(--gold-primary);
            transform: rotate(45deg);
            position: relative;
        }

        .luxury-divider .diamond::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 4px;
            height: 4px;
            background: var(--gold-primary);
            transform: translate(-50%, -50%);
        }

        /* Stats Section */
        .stats-section {
            background: linear-gradient(180deg, var(--black-deep) 0%, var(--black-soft) 50%, var(--black-deep) 100%);
            border-top: 1px solid rgba(212, 175, 55, 0.1);
            border-bottom: 1px solid rgba(212, 175, 55, 0.1);
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 60px;
            max-width: 1200px;
            margin: 0 auto;
            text-align: center;
        }

        .stat-item {
            position: relative;
        }

        .stat-item::after {
            content: '';
            position: absolute;
            right: -30px;
            top: 50%;
            transform: translateY(-50%);
            width: 1px;
            height: 60px;
            background: linear-gradient(180deg, transparent, var(--gold-primary), transparent);
        }

        .stat-item:last-child::after {
            display: none;
        }

        .stat-number {
            font-family: 'Playfair Display', serif;
            font-size: 64px;
            font-weight: 700;
            background: linear-gradient(135deg, var(--gold-light), var(--gold-primary), var(--gold-dark));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            line-height: 1;
            margin-bottom: 15px;
        }

        .stat-label {
            font-size: 12px;
            letter-spacing: 4px;
            text-transform: uppercase;
            color: var(--white-muted);
        }

        /* Showcase Section */
        .showcase {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 80px;
            max-width: 1400px;
            margin: 0 auto;
            align-items: center;
        }

        .showcase-content h2 {
            font-family: 'Playfair Display', serif;
            font-size: 48px;
            margin-bottom: 30px;
            line-height: 1.2;
        }

        .showcase-content h2 span {
            color: var(--gold-primary);
            font-style: italic;
        }

        .showcase-content p {
            font-size: 16px;
            line-height: 1.8;
            color: var(--white-muted);
            margin-bottom: 30px;
        }

        .showcase-features {
            list-style: none;
        }

        .showcase-features li {
            padding: 15px 0;
            border-bottom: 1px solid rgba(212, 175, 55, 0.1);
            display: flex;
            align-items: center;
            gap: 20px;
            font-size: 14px;
            letter-spacing: 1px;
        }

        .showcase-features li::before {
            content: '◆';
            color: var(--gold-primary);
            font-size: 10px;
        }

        .showcase-visual {
            position: relative;
            height: 500px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .gold-frame {
            width: 400px;
            height: 400px;
            border: 1px solid var(--gold-primary);
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            animation: rotateFrame 20s linear infinite;
        }

        @keyframes rotateFrame {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
        }

        .gold-frame::before,
        .gold-frame::after {
            content: '';
            position: absolute;
            border: 1px solid rgba(212, 175, 55, 0.3);
        }

        .gold-frame::before {
            width: 350px;
            height: 350px;
        }

        .gold-frame::after {
            width: 300px;
            height: 300px;
        }

        .gold-frame-inner {
            width: 200px;
            height: 200px;
            background: radial-gradient(circle, rgba(212, 175, 55, 0.2), transparent);
            border: 1px solid var(--gold-primary);
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: 'Playfair Display', serif;
            font-size: 48px;
            color: var(--gold-primary);
            animation: rotateFrame 20s linear infinite reverse;
        }

        /* Contact Section */
        .contact-section {
            text-align: center;
            background: linear-gradient(180deg, var(--black-deep) 0%, rgba(212, 175, 55, 0.03) 50%, var(--black-deep) 100%);
        }

        .contact-content {
            max-width: 800px;
            margin: 0 auto;
        }

        .contact-content h2 {
            font-family: 'Playfair Display', serif;
            font-size: 56px;
            margin-bottom: 30px;
        }

        .contact-content h2 span {
            color: var(--gold-primary);
            font-style: italic;
        }

        .contact-content p {
            font-family: 'Cormorant Garamond', serif;
            font-size: 22px;
            font-style: italic;
            color: var(--white-muted);
            margin-bottom: 50px;
            line-height: 1.6;
        }

        /* Footer */
        footer {
            background: var(--black-deep);
            padding: 80px 60px 40px;
            border-top: 1px solid rgba(212, 175, 55, 0.15);
            position: relative;
            z-index: 1;
        }

        .footer-content {
            max-width: 1400px;
            margin: 0 auto;
        }

        .footer-top {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 60px;
            margin-bottom: 60px;
        }

        .footer-brand {
            font-family: 'Playfair Display', serif;
            font-size: 32px;
            letter-spacing: 4px;
            margin-bottom: 20px;
        }

        .footer-brand span {
            color: var(--gold-primary);
        }

        .footer-tagline {
            font-family: 'Cormorant Garamond', serif;
            font-size: 18px;
            font-style: italic;
            color: var(--white-muted);
            line-height: 1.6;
        }

        .footer-col h4 {
            font-size: 11px;
            letter-spacing: 4px;
            text-transform: uppercase;
            color: var(--gold-primary);
            margin-bottom: 25px;
        }

        .footer-col ul {
            list-style: none;
        }

        .footer-col ul li {
            margin-bottom: 12px;
        }

        .footer-col ul li a {
            color: var(--white-muted);
            text-decoration: none;
            font-size: 13px;
            letter-spacing: 1px;
            transition: color 0.3s, padding-left 0.3s;
        }

        .footer-col ul li a:hover {
            color: var(--gold-primary);
            padding-left: 10px;
        }

        .footer-bottom {
            padding-top: 40px;
            border-top: 1px solid rgba(212, 175, 55, 0.1);
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 20px;
        }

        .footer-copy {
            font-size: 11px;
            letter-spacing: 2px;
            color: var(--white-muted);
        }

        .social-links {
            display: flex;
            gap: 25px;
        }

        .social-link {
            width: 45px;
            height: 45px;
            border: 1px solid rgba(212, 175, 55, 0.3);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
            color: var(--gold-primary);
            transition: all 0.4s;
            cursor: pointer;
            position: relative;
            overflow: hidden;
        }

        .social-link::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 0;
            height: 0;
            background: var(--gold-primary);
            border-radius: 50%;
            transform: translate(-50%, -50%);
            transition: width 0.4s, height 0.4s;
            z-index: -1;
        }

        .social-link:hover {
            color: var(--black-deep);
            border-color: var(--gold-primary);
            transform: translateY(-5px);
        }

        .social-link:hover::before {
            width: 100%;
            height: 100%;
        }

        /* Reveal Animation */
        .reveal {
            opacity: 0;
            transform: translateY(60px);
            transition: all 1s cubic-bezier(0.25, 0.46, 0.45, 0.94);
        }

        .reveal.active {
            opacity: 1;
            transform: translateY(0);
        }

        /* Responsive */
        @media (max-width: 968px) {
            .nav-links { gap: 25px; }
            .nav-links a { font-size: 10px; letter-spacing: 2px; }
            section { padding: 100px 30px; }
            .showcase { grid-template-columns: 1fr; gap: 60px; }
            .footer-top { grid-template-columns: 1fr 1fr; gap: 40px; }
            .stat-item::after { display: none; }
            nav { padding: 20px 30px; }
        }

        @media (max-width: 600px) {
            .nav-links { display: none; }
            .footer-top { grid-template-columns: 1fr; }
            .footer-bottom { flex-direction: column; text-align: center; }
            .hero-title { letter-spacing: 4px; }
        }
    </style>
</head>
